## File 2: ChatEntry.vue

```vue /home/codx-junior-projects/codx-junior/client/src/components/ChatEntry.vue
<script setup>
import Document from './document/Document.vue'
import CodeBlock from './CodeBlock.vue'
import ChatMessage from './ChatMessage.vue'
</script>

<template>
  <div
    class="chat-entry-container space-y-4"
    :class="{ 'opacity-50': message.loading }"
  >
    <!-- Message header with metadata -->
    <div class="flex items-center justify-between px-4 py-2 bg-gray-50 dark:bg-gray-800 rounded-lg">
      <div class="flex items-center gap-2">
        <span class="text-sm font-semibold text-gray-900 dark:text-gray-100">
          {{ message.role === 'user' ? 'You' : 'Assistant' }}
        </span>
        <span v-if="message.timestamp" class="text-xs text-gray-500 dark:text-gray-400">
          {{ formatTime(message.timestamp) }}
        </span>
      </div>

      <div class="flex gap-2">
        <!-- Edit button for user messages -->
        <button
          v-if="message.role === 'user'"
          class="btn btn-sm btn-ghost btn-circle"
          @click="$emit('edit-message', message)"
          title="Edit message"
        >
          <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
          </svg>
        </button>

        <!-- Copy button -->
        <button
          class="btn btn-sm btn-ghost btn-circle"
          @click="copyMessageContent"
          title="Copy message"
        >
          <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z" />
          </svg>
        </button>

        <!-- Delete button -->
        <button
          class="btn btn-sm btn-ghost btn-circle"
          @click="$emit('delete-message', message)"
          title="Delete message"
        >
          <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
          </svg>
        </button>
      </div>
    </div>

    <!-- Message content - different views based on mode -->
    <div class="space-y-4">
      <!-- Diff view -->
      <div v-if="showDiff" class="bg-white dark:bg-gray-900 rounded-lg p-4">
        <!-- Diff content would be rendered here -->
        <div class="text-sm text-gray-600 dark:text-gray-400">Diff View</div>
      </div>

      <!-- Source/Code view -->
      <div v-else-if="srcView" class="bg-white dark:bg-gray-900 rounded-lg p-4">
        <pre class="overflow-auto text-xs font-mono">{{ messageContent }}</pre>
      </div>

      <!-- PR view -->
      <div v-else-if="showPRView" class="bg-white dark:bg-gray-900 rounded-lg p-4">
        <!-- PR content would be rendered here -->
        <div class="text-sm text-gray-600 dark:text-gray-400">PR View</div>
      </div>

      <!-- Code patches view -->
      <div v-else-if="codPatches" class="space-y-2">
        <div v-for="(patch, idx) in codePatches" :key="`patch-${idx}`" class="bg-white dark:bg-gray-900 rounded-lg p-4">
          <!-- Patch content -->
          <pre class="overflow-auto text-xs font-mono">{{ patch.content }}</pre>
        </div>
      </div>

      <!-- Word document view -->
      <div v-else-if="isWord" class="bg-white dark:bg-gray-900 rounded-lg p-4">
        <!-- Word document rendering -->
        <div class="text-sm text-gray-600 dark:text-gray-400">Document Preview</div>
      </div>

      <!-- Standard document view with reactivity fix -->
      <Document
        v-else
        :key="`doc-${message.doc_id}-${contentLength}-${message.id}`"
        :content="messageContent"
        :files="chatFiles"
        :project="chatProject"
        :chat="chat"
        :loading="!message.done"
        :documentId="documentId"
        :message="message"
        :mentionList="mentionList"
        @generate-code="onGenerateCode"
        @reload-file="onReloadFile"
        @open-file="$emit('open-file', $event)"
        @save-file="$emit('save-file', $event)"
        @add-file="$emit('add-file', $event)"
        @edit-message="$emit('edit-message', $event)"
        @sub-task="$emit('sub-task', $event)"
        @copy-chapter="onCopyChapter"
        @create-task="onCreateTask"
      />
    </div>

    <!-- Message actions footer -->
    <div v-if="showActions" class="flex flex-wrap gap-2 pt-2">
      <button
        v-if="message.role === 'assistant'"
        class="btn btn-sm btn-outline"
        @click="$emit('regenerate', message)"
      >
        Regenerate
      </button>
      <button
        class="btn btn-sm btn-outline"
        @click="toggleSourceView"
      >
        {{ srcView ? 'Hide Source' : 'Show Source' }}
      </button>
    </div>
  </div>
</template>

<script>
export default {
  name: 'ChatEntry',
  components: {
    Document: () => import('./document/Document.vue'),
    ChatMessage: () => import('./ChatMessage.vue')
  },
  props: {
    message: {
      type: Object,
      required: true
    },
    chat: {
      type: Object,
      default: null
    },
    chatFiles: {
      type: Array,
      default: null
    },
    chatProject: {
      type: Object,
      default: null
    },
    mentionList: {
      type: Array,
      default: () => []
    },
    documentId: {
      type: String,
      default: ''
    },
    showActions: {
      type: Boolean,
      default: true
    }
  },
  emits: [
    'generate-code',
    'reload-file',
    'open-file',
    'save-file',
    'add-file',
    'edit-message',
    'delete-message',
    'sub-task',
    'copy-chapter',
    'create-task',
    'regenerate'
  ],
  data() {
    return {
      srcView: false,
      showDiff: false,
      showPRView: false,
      codePatches: [],
      isWord: false,
      contentLength: 0
    }
  },
  computed: {
    // Get message content from different sources
    messageContent() {
      if (this.message.content) {
        this.contentLength = (this.message.content || '').length
        return this.message.content
      }
      if (this.message.result) {
        this.contentLength = (this.message.result || '').length
        return this.message.result
      }
      if (this.message.markdown) {
        this.contentLength = (this.message.markdown || '').length
        return this.message.markdown
      }
      return ''
    }
  },
  watch: {
    // Watch message content changes
    'message.content'() {
      this.contentLength = (this.message.content || '').length
    },
    'message.result'() {
      this.contentLength = (this.message.result || '').length
    }
  },
  methods: {
    // Format timestamp for display
    formatTime(timestamp) {
      if (!timestamp) return ''
      const date = new Date(timestamp)
      return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    },
    // Copy message content to clipboard
    async copyMessageContent() {
      try {
        await navigator.clipboard.writeText(this.messageContent)
        this.$toast?.success('Message copied to clipboard')
      } catch (err) {
        console.error('Failed to copy message', err)
        this.$toast?.error('Failed to copy message')
      }
    },
    // Toggle source code view
    toggleSourceView() {
      this.srcView = !this.srcView
    },
    // Handle code generation event
    onGenerateCode(data) {
      this.$emit('generate-code', {
        ...data,
        messageId: this.message.id
      })
    },
    // Handle file reload event
    onReloadFile(data) {
      this.$emit('reload-file', {
        ...data,
        messageId: this.message.id
      })
    },
    // Handle chapter copy event
    onCopyChapter(data) {
      this.$emit('copy-chapter', {
        ...data,
        messageId: this.message.id
      })
    },
    // Handle task creation event
    onCreateTask(data) {
      this.$emit('create-task', {
        ...data,
        messageId: this.message.id
      })
    }
  }
}
</script>
```

